/*
 * area_$find_entry_by_uid - locate (activating if need be) the ASTE that
 * backs one area segment
 *
 * Original address: 0x00E0939C (module-local; the SAU2 map has no symbol
 * here, Ghidra carries the tree name)
 * Size: 354 bytes (0x00E0939C .. 0x00E094FD)
 * Generated by: Claude Opus 5.5
 *
 * Callers: AREA_$TOUCH (0x00E095AE), AREA_$ASSOC (0x00E096D4) and
 * 0x00E099AC; all run with A5 = 0xE1E118 (AREA_$GLOBALS), which this
 * routine uses without loading.
 *
 * Frame (link.w A6,-0x1c; D2-D4/A2-A4 saved):
 *   (0x08,A6) area_id   word -> D3w
 *   (0x0A,A6) bste_ptr  VAR word -> A2: the area-relative segment index;
 *                       rewritten for a reversed area
 *   (0x0E,A6) page      word -> D0w
 *   (0x10,A6) status_p  -> A3
 *   (-0x0C)   slot      the area_$seg_slot_t of the segment
 * A0 = 0xD94C00 + area_id*0x30 (one past the entry; its fields at
 * negative displacements).  The result is returned in A0, moved from A2.
 *
 * Blocks:
 *   0x00E093B4  *status_p := 0
 *   0x00E093CC-0x00E093DA  AREA_FLAG_ACTIVE clear (`lsr.b #1` / `bcs` on the
 *                          flags word's low byte): status 0x00320006
 *   0x00E093DE-0x00E09410  reversed area: *bste_ptr := -1 - *bste_ptr; the
 *                          page (*bste_ptr << 5) + 0x1F - page must not be
 *                          above (virt_size - 1) >> 10 (SIGNED `ble`)
 *   0x00E09412-0x00E0942A  otherwise page + (*bste_ptr << 5) must not be
 *                          above the same limit (UNSIGNED `bls`)
 *   0x00E0942C  beyond it: status 0x00030001
 *   0x00E09436-0x00E0945A  n := (page + (*bste_ptr << 5)) >> 8; n < 2:
 *                          slot := &entry->seg_bitmap[n]
 *   0x00E0945C-0x00E094BC  n >= 2: find the overflow table (area id and
 *                          (n - 2) >> 8) on seg_table_list[owner_asid]
 *                          (none -> CRASH_SYSTEM(Area_Internal_Error));
 *                          slot := bitmap_ptr + ((n - 2) mod 0x100) * 4
 *   0x00E094C0-0x00E094F0  under ML lock 0x12: area_$get_aste(area_id,
 *                          slot, *bste_ptr, wait FALSE, create TRUE,
 *                          status_p)
 *
 * Quirk: both early exits (not active, beyond the size) return A2, which
 * still holds bste_ptr - the C returns that pointer, cast, as the image
 * does; the callers test *status_p first.
 */

#include "area/area_internal.h"
#include "misc/crash_system.h"

/* `lsr.l #0x8,D2` 0x00E09446 and `cmpi.w #0x2,D2w` 0x00E09448: the first
 * two slot cells live in the entry, the rest in 0x100-cell overflow
 * tables (`move.w #0x100,-(SP)` 0x00E094A4) */
#define AREA_INLINE_SLOTS       2
#define AREA_SLOTS_PER_TABLE    0x100

struct aste_t *area_$find_entry_by_uid(int16_t area_id, uint16_t *bste_ptr,
                                       int16_t page, status_$t *status_p)
{
    area_$entry_t *entry;           /* A0 - 0x30 */
    area_$seg_table_t *tbl;         /* A4 */
    area_$seg_slot_t *slot;         /* (-0xc,A6) */
    uint16_t n;                     /* D2w */
    uint16_t table_idx;             /* D0w */
    uint32_t limit;                 /* D1 */
    struct aste_t *aste;

    /* 0x00E093B4 */
    *status_p = status_$ok;

    /* 0x00E093B6-0x00E093DA */
    entry = AREA_ID_TO_ENTRY((uint16_t)area_id);
    if ((entry->flags & AREA_FLAG_ACTIVE) == 0) {
        *status_p = status_$area_not_active;
        return (struct aste_t *)bste_ptr;
    }

    limit = (entry->virt_size - 1) >> 10;
    if ((entry->flags & AREA_FLAG_REVERSED) != 0) {
        /* 0x00E093E8-0x00E0940E */
        *bste_ptr = (uint16_t)(0xFFFF - *bste_ptr);
        if (!((int32_t)(((uint32_t)*bste_ptr << 5) + 0x1F - (uint16_t)page) <=
              (int32_t)limit)) {
            *status_p = status_$ast_eof;
            return (struct aste_t *)bste_ptr;
        }
    } else {
        /* 0x00E09412-0x00E0942A */
        if (!((uint32_t)(uint16_t)page + ((uint32_t)*bste_ptr << 5) <= limit)) {
            *status_p = status_$ast_eof;
            return (struct aste_t *)bste_ptr;
        }
    }

    /* 0x00E09436-0x00E09448 */
    n = (uint16_t)(((uint32_t)(uint16_t)page + ((uint32_t)*bste_ptr << 5)) >> 8);
    if (n < AREA_INLINE_SLOTS) {
        /* 0x00E0944E-0x00E0945A */
        slot = (area_$seg_slot_t *)&entry->seg_bitmap[n];
    } else {
        /* 0x00E0945C-0x00E09488 */
        table_idx = (uint16_t)((uint16_t)(n - AREA_INLINE_SLOTS) >> 8);
        tbl = AREA_$GLOBALS.seg_table_list[entry->owner_asid];
        while (tbl != NULL) {
            if (tbl->area_id == area_id &&
                (uint16_t)tbl->table_index == table_idx) {
                break;
            }
            tbl = (area_$seg_table_t *)ARCH_VA_TO_PTR(tbl->next);
        }

        /* 0x00E0948A-0x00E0949A */
        if (tbl == NULL) {
            CRASH_SYSTEM(&Area_Internal_Error);
        }

        /* 0x00E0949C-0x00E094BC */
        slot = (area_$seg_slot_t *)((char *)ARCH_VA_TO_PTR(tbl->bitmap_ptr) +
               (int16_t)(uint16_t)((uint16_t)M$OIS$WLW(
                   (long)((uint32_t)n - AREA_INLINE_SLOTS),
                   AREA_SLOTS_PER_TABLE) << 2));
    }

    /* 0x00E094C0-0x00E094F0 */
    ML_$LOCK(ML_LOCK_AST);
    aste = area_$get_aste(area_id, slot, (int16_t)*bste_ptr, 0, (int8_t)-1,
                          status_p);
    ML_$UNLOCK(ML_LOCK_AST);
    return aste;
}
